-- =============================================================
-- Method A restore: put app data back from a backup JSON (backup_tables.sql / backup_tables_latest.sql)
-- while KEEPING the Auth users exactly as they are. Auth itself is never read for content nor changed.
-- Method A cannot recover a loss of Auth users (that is method B: docs/internal/PHASE6_BACKUP_RESTORE_DESIGN.md).
--
-- Do not edit this file by hand to run it. Build the runnable SQL (the backup is embedded) OUTSIDE any repository:
--   node scripts/ops/build-restore-sql.mjs <tables.json> <out.sql> plan [--scope missing-teams|all]
--   node scripts/ops/build-restore-sql.mjs <tables.json> <out.sql> commit --expect-missing-teams <N> [--scope ...]
--   supabase db query --linked --agent no -f <out.sql>
--
-- What it restores (rows are only ADDED, never overwritten or deleted, except the join token a restored team got
-- from the trigger a moment earlier):
--   scope missing-teams (default): teams that no longer exist, with everything under them; deletion-state records.
--   scope all: additionally, inside teams that still exist, missing events, answers and no-longer-usable invitations.
--     Missing memberships, registrations, guardian links, re-join blocks, still-usable invitations or still-valid
--     owner hand-overs inside an existing team may be intentional changes made after the backup (leave, removal,
--     cancellation, unblock, revoke ...): the restore cannot judge that, so it STOPS instead of reviving them.
-- Rows that exist but differ from the backup (a wrong update) are only COUNTED ("differs"); they are not changed.
--
-- Safety
--   * One DO block = one statement = one transaction: everything or nothing. Writes to the app tables are blocked
--     (SHARE ROW EXCLUSIVE locks) from the first check to the end, so nothing can change in between.
--   * plan: runs every check and every insert, then raises RESTORE_PLAN with the report -> everything rolled back.
--   * commit: only with --expect-missing-teams equal to what plan showed; ends normally when all post-checks pass.
--   * Stops (restore_aborted / post-check failed, nothing changed) when: the database is not Phase 4-B nor the latest;
--     its structure disagrees with the migration history; the backup format, kind, migration list, counts, row shape
--     or keys are wrong; a newer backup would go into an older schema; ANY Auth user referenced by the backup is
--     missing; rows would revive data of a user in the middle of account deletion; tokens would collide; the
--     number of whole teams differs from the expectation; or a security invariant is broken afterwards.
--   * Messages contain counts only: never names, e-mails, ids or tokens.
--   * Run as the database owner (Supabase CLI / SQL editor), never through the app's API.
-- =============================================================
do $restore$
declare
  v_mode   text := '__MODE__';
  v_scope  text := '__SCOPE__';
  v_expect int  := __EXPECT_MISSING_TEAMS__;
  b        jsonb := __BACKUP__;
  c_4b     text[] := array['20261107000000','20261108000000','20261109000000','20261110000000','20261113000000','20261113100000'];
  c_latest text[] := array['20261107000000','20261108000000','20261109000000','20261110000000','20261113000000','20261113100000',
                           '20261117000000','20261117100000','20261117200000','20261117230000','20261117233000','20261117234500',
                           '20261117235500','20261118000000','20261118100000','20261118200000','20261118210000'];
  c_meta   text[] := array['format','kind','taken_at','migrations','auth_users_count','counts'];
  v_db text[]; v_target text; v_kind text; v_tables text[];
  t text; k text; n bigint; m bigint; x bigint; v_missing int;
  v_cfg jsonb; v_rep text := ''; v_conf text := ''; v_post text := '';
  v_new_tokens int := 0;
begin
  if v_mode not in ('plan', 'commit') or v_scope not in ('missing-teams', 'all') then
    raise exception 'restore_aborted: invalid mode or scope';
  end if;
  if v_mode = 'commit' and v_expect < 0 then
    raise exception 'restore_aborted: commit needs --expect-missing-teams (run plan first)';
  end if;
  if auth.uid() is not null then
    raise exception 'restore_aborted: run this as the database owner, not as an app user';
  end if;

  -- ---------------------------------------------------------------
  -- 1. Target database: migration history and structure
  -- ---------------------------------------------------------------
  begin
    select coalesce(array_agg(version::text order by version), '{}') into v_db from supabase_migrations.schema_migrations;
  exception when undefined_table then
    raise exception 'restore_aborted: migration history (supabase_migrations.schema_migrations) not found';
  end;
  v_target := case when v_db = c_4b then 'phase4b' when v_db = c_latest then 'latest' end;
  if v_target is null then
    raise exception 'restore_aborted: the database is neither Phase 4-B (6 migrations) nor the latest (17 migrations): % applied', cardinality(v_db);
  end if;
  if to_regclass('public.team_owner_transfers') is null or to_regclass('private.account_deletions') is null
     or (to_regclass('private.team_join_tokens') is not null) <> (v_target = 'latest')
     or (to_regclass('private.team_member_blocks') is not null) <> (v_target = 'latest')
     or exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'players' and column_name = 'is_self') <> (v_target = 'latest')
     or exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'team_members' and column_name = 'suspended_at') <> (v_target = 'latest') then
    raise exception 'restore_aborted: the database structure does not match its migration history (%)', v_target;
  end if;

  -- no app write may happen between the checks and the end (reads stay possible)
  lock table public.teams, public.team_members, public.players, public.player_guardians, public.events, public.attendance,
             public.guardian_invitations, public.team_owner_transfers, private.account_deletions in share row exclusive mode;
  if v_target = 'latest' then
    execute 'lock table private.team_join_tokens, private.team_member_blocks in share row exclusive mode';
  end if;

  -- ---------------------------------------------------------------
  -- 2. Backup integrity
  -- ---------------------------------------------------------------
  if jsonb_typeof(b) is distinct from 'object' or b ->> 'format' is distinct from '3' then
    raise exception 'restore_aborted: unsupported backup format (expected format 3 from backup_tables*.sql)';
  end if;
  v_kind := b ->> 'kind';
  if v_kind is null or v_kind not in ('phase4b', 'latest') then
    raise exception 'restore_aborted: unknown backup kind';
  end if;
  if (v_kind = 'phase4b' and b -> 'migrations' is distinct from to_jsonb(c_4b))
     or (v_kind = 'latest' and b -> 'migrations' is distinct from to_jsonb(c_latest)) then
    raise exception 'restore_aborted: the backup''s migration list does not match its kind (%): taken with the wrong backup file?', v_kind;
  end if;
  if v_kind = 'latest' and v_target = 'phase4b' then
    raise exception 'restore_aborted: a latest-schema backup cannot be restored into a Phase 4-B database';
  end if;
  v_tables := array['teams','team_members','players','player_guardians','events','attendance','guardian_invitations',
                    'team_owner_transfers','account_deletions']
              || case when v_kind = 'latest' then array['team_join_tokens','team_member_blocks'] else '{}'::text[] end;
  for k in select jsonb_object_keys(b) loop
    if not (k = any (c_meta) or k = any (v_tables)) then
      raise exception 'restore_aborted: unexpected key in the backup';
    end if;
  end loop;
  if jsonb_typeof(b -> 'counts') is distinct from 'object' then
    raise exception 'restore_aborted: the backup has no counts';
  end if;
  foreach t in array v_tables loop
    if jsonb_typeof(b -> t) is distinct from 'array' then
      raise exception 'restore_aborted: table % is missing in the backup', t;
    end if;
    if (b -> 'counts' ->> t) is null or jsonb_array_length(b -> t) <> (b -> 'counts' ->> t)::bigint then
      raise exception 'restore_aborted: table % has % rows but the backup recorded % (file truncated or edited?)',
        t, jsonb_array_length(b -> t), coalesce(b -> 'counts' ->> t, '-');
    end if;
    if exists (select 1 from jsonb_array_elements(b -> t) e where jsonb_typeof(e.value) <> 'object') then
      raise exception 'restore_aborted: table % has a malformed row', t;
    end if;
  end loop;
  -- columns added after 4-B must be absent in a 4-B backup and present in a latest one
  if v_kind = 'phase4b' and (exists (select 1 from jsonb_array_elements(b -> 'players') e where e.value ? 'is_self' or e.value ? 'self_user_id')
                          or exists (select 1 from jsonb_array_elements(b -> 'team_members') e where e.value ? 'suspended_at' or e.value ? 'access_revision')) then
    raise exception 'restore_aborted: a Phase 4-B backup carries columns of a later schema';
  end if;
  if v_kind = 'latest' and (exists (select 1 from jsonb_array_elements(b -> 'players') e where not (e.value ? 'is_self' and e.value ? 'self_user_id'))
                         or exists (select 1 from jsonb_array_elements(b -> 'team_members') e where not (e.value ? 'suspended_at' and e.value ? 'access_revision'))) then
    raise exception 'restore_aborted: a latest backup lacks columns of the latest schema';
  end if;

  -- typed copies of the backup (4-B rows are read with the 4-B columns only, so they also fit the latest tables)
  create temp table bk_teams on commit drop as select * from jsonb_populate_recordset(null::public.teams, b -> 'teams');
  if v_kind = 'latest' then
    create temp table bk_members on commit drop as select * from jsonb_populate_recordset(null::public.team_members, b -> 'team_members');
    create temp table bk_players on commit drop as select * from jsonb_populate_recordset(null::public.players, b -> 'players');
    create temp table bk_tokens  on commit drop as select * from jsonb_populate_recordset(null::private.team_join_tokens, b -> 'team_join_tokens');
    create temp table bk_blocks  on commit drop as select * from jsonb_populate_recordset(null::private.team_member_blocks, b -> 'team_member_blocks');
  else
    create temp table bk_members on commit drop as select * from jsonb_to_recordset(b -> 'team_members')
      as x(team_id uuid, user_id uuid, role text, display_name text, joined_at timestamptz);
    create temp table bk_players on commit drop as select * from jsonb_to_recordset(b -> 'players')
      as x(id uuid, team_id uuid, name text, normalized_name text, note text, created_by uuid, created_at timestamptz,
           archived_at timestamptz, updated_at timestamptz, updated_by uuid, archived_by uuid);
  end if;
  create temp table bk_guardians   on commit drop as select * from jsonb_populate_recordset(null::public.player_guardians, b -> 'player_guardians');
  create temp table bk_events      on commit drop as select * from jsonb_populate_recordset(null::public.events, b -> 'events');
  create temp table bk_attendance  on commit drop as select * from jsonb_populate_recordset(null::public.attendance, b -> 'attendance');
  create temp table bk_invitations on commit drop as select * from jsonb_populate_recordset(null::public.guardian_invitations, b -> 'guardian_invitations');
  create temp table bk_transfers   on commit drop as select * from jsonb_populate_recordset(null::public.team_owner_transfers, b -> 'team_owner_transfers');
  create temp table bk_deletions   on commit drop as select * from jsonb_populate_recordset(null::private.account_deletions, b -> 'account_deletions');

  -- table name, temp copy, real table, primary key
  v_cfg := jsonb_build_array(
    jsonb_build_array('teams', 'bk_teams', 'public.teams', 'id'),
    jsonb_build_array('team_members', 'bk_members', 'public.team_members', 'team_id, user_id'),
    jsonb_build_array('players', 'bk_players', 'public.players', 'id'),
    jsonb_build_array('player_guardians', 'bk_guardians', 'public.player_guardians', 'player_id, user_id'),
    jsonb_build_array('events', 'bk_events', 'public.events', 'id'),
    jsonb_build_array('attendance', 'bk_attendance', 'public.attendance', 'event_id, player_id'),
    jsonb_build_array('guardian_invitations', 'bk_invitations', 'public.guardian_invitations', 'id'),
    jsonb_build_array('team_owner_transfers', 'bk_transfers', 'public.team_owner_transfers', 'team_id'),
    jsonb_build_array('account_deletions', 'bk_deletions', 'private.account_deletions', 'user_id'))
    || case when v_kind = 'latest' then jsonb_build_array(
    jsonb_build_array('team_join_tokens', 'bk_tokens', 'private.team_join_tokens', 'team_id'),
    jsonb_build_array('team_member_blocks', 'bk_blocks', 'private.team_member_blocks', 'team_id, user_id')) else '[]'::jsonb end;

  -- no row without its key, no key twice
  for i in 0 .. jsonb_array_length(v_cfg) - 1 loop
    execute format('select count(*), count(distinct (%s)) filter (where (%s) is not null and %s) from %I',
      v_cfg -> i ->> 3, v_cfg -> i ->> 3,
      (select string_agg(trim(c) || ' is not null', ' and ') from unnest(string_to_array(v_cfg -> i ->> 3, ',')) c),
      v_cfg -> i ->> 1) into n, m;
    if n <> m then
      raise exception 'restore_aborted: table % in the backup has rows without a key or the same key twice', v_cfg -> i ->> 0;
    end if;
  end loop;

  -- ---------------------------------------------------------------
  -- 3. Every Auth user the backup refers to must still exist (method A never creates Auth users)
  -- ---------------------------------------------------------------
  select count(*) into v_missing from (
    select distinct e.value ->> c as uid
      from unnest(v_tables) tn
      cross join lateral jsonb_array_elements(b -> tn) e
      cross join unnest(array['user_id','created_by','updated_by','deleted_by','archived_by','used_by','self_user_id','from_user','to_user']) c
     where e.value ? c and e.value ->> c is not null) u
   where not exists (select 1 from auth.users a where a.id = u.uid::uuid);
  if v_missing > 0 then
    raise exception 'restore_aborted: % Auth user(s) referenced by the backup no longer exist; nothing was changed (method A restores no Auth users)', v_missing;
  end if;

  -- ---------------------------------------------------------------
  -- 4. What would be restored, and what cannot be judged
  -- ---------------------------------------------------------------
  create temp table rt on commit drop as
    select id from bk_teams b1 where not exists (select 1 from public.teams t1 where t1.id = b1.id);
  create temp table et on commit drop as
    select id from bk_teams b1 where exists (select 1 from public.teams t1 where t1.id = b1.id);

  create temp table ins_teams on commit drop as select * from bk_teams where id in (select id from rt);
  create temp table ins_members on commit drop as select * from bk_members where team_id in (select id from rt);
  create temp table ins_players on commit drop as select * from bk_players where team_id in (select id from rt);
  create temp table ins_guardians on commit drop as select * from bk_guardians where team_id in (select id from rt);
  create temp table ins_events on commit drop as
    select * from bk_events e where e.team_id in (select id from rt)
       or (v_scope = 'all' and e.team_id in (select id from et) and not exists (select 1 from public.events d where d.id = e.id));
  create temp table ins_attendance on commit drop as
    select * from bk_attendance a where a.team_id in (select id from rt)
       or (v_scope = 'all' and a.team_id in (select id from et)
           and not exists (select 1 from public.attendance d where d.event_id = a.event_id and d.player_id = a.player_id)
           and exists (select 1 from public.players p where p.id = a.player_id)
           and (exists (select 1 from public.events d where d.id = a.event_id) or a.event_id in (select id from ins_events)));
  create temp table ins_invitations on commit drop as
    select * from bk_invitations i where i.team_id in (select id from rt)
       or (v_scope = 'all' and i.team_id in (select id from et)
           and not exists (select 1 from public.guardian_invitations d where d.id = i.id)
           and exists (select 1 from public.players p where p.id = i.player_id)
           and (i.used_at is not null or i.revoked_at is not null or i.expires_at <= now()));
  create temp table ins_transfers on commit drop as select * from bk_transfers where team_id in (select id from rt);
  create temp table ins_deletions on commit drop as
    select * from bk_deletions b1 where not exists (select 1 from private.account_deletions d where d.user_id = b1.user_id);
  if v_kind = 'latest' then
    create temp table ins_tokens on commit drop as select * from bk_tokens where team_id in (select id from rt);
    create temp table ins_blocks on commit drop as select * from bk_blocks where team_id in (select id from rt);
    if exists (select 1 from rt where id not in (select team_id from bk_tokens)) then
      raise exception 'restore_aborted: the backup has a team without its join-token row (inconsistent backup)';
    end if;
  end if;

  -- changes inside EXISTING teams that may have been made on purpose after the backup
  v_conf := '';
  select count(*) into n from bk_members b1 where b1.team_id in (select id from et)
     and not exists (select 1 from public.team_members d where d.team_id = b1.team_id and d.user_id = b1.user_id);
  if n > 0 then v_conf := v_conf || format(' memberships=%s', n); end if;
  select count(*) into n from bk_players b1 where b1.team_id in (select id from et)
     and not exists (select 1 from public.players d where d.id = b1.id);
  if n > 0 then v_conf := v_conf || format(' registrations=%s', n); end if;
  select count(*) into n from bk_guardians b1 where b1.team_id in (select id from et)
     and not exists (select 1 from public.player_guardians d where d.player_id = b1.player_id and d.user_id = b1.user_id);
  if n > 0 then v_conf := v_conf || format(' guardian_links=%s', n); end if;
  select count(*) into n from bk_invitations b1 where b1.team_id in (select id from et)
     and not exists (select 1 from public.guardian_invitations d where d.id = b1.id)
     and b1.used_at is null and b1.revoked_at is null and b1.expires_at > now();
  if n > 0 then v_conf := v_conf || format(' usable_invitations=%s', n); end if;
  select count(*) into n from bk_transfers b1 where b1.team_id in (select id from et)
     and not exists (select 1 from public.team_owner_transfers d where d.team_id = b1.team_id) and b1.expires_at > now();
  if n > 0 then v_conf := v_conf || format(' valid_owner_handovers=%s', n); end if;
  if v_kind = 'latest' then
    select count(*) into n from bk_blocks b1 where b1.team_id in (select id from et)
       and not exists (select 1 from private.team_member_blocks d where d.team_id = b1.team_id and d.user_id = b1.user_id);
    if n > 0 then v_conf := v_conf || format(' rejoin_blocks=%s', n); end if;
  end if;
  if v_scope = 'all' and v_conf <> '' then
    raise exception 'restore_aborted: inside teams that still exist the backup differs in security-relevant rows (%): they may have been changed on purpose after the backup; restore them by hand after checking each one', trim(v_conf);
  end if;

  -- never bring back data of a user who is in the middle of account deletion
  select count(*) into n from (
    select user_id from ins_members union all select user_id from ins_guardians
    union all select (to_jsonb(p) ->> 'self_user_id')::uuid from ins_players p   -- 4-B rows have no self_user_id
  ) u where u.user_id in (select user_id from private.account_deletions);
  if n > 0 then
    raise exception 'restore_aborted: % row(s) would revive data of a user whose account deletion is in progress', n;
  end if;
  -- unique values must not collide with rows created after the backup
  if exists (select 1 from ins_teams i join public.teams t1 on t1.share_token = i.share_token)
     or exists (select 1 from ins_invitations i join public.guardian_invitations g on g.token_hash = i.token_hash and g.id <> i.id) then
    raise exception 'restore_aborted: a share token or invitation token of the backup is already used by another row';
  end if;
  if v_kind = 'latest' then   -- (nested: the temp table only exists for a latest backup)
    if exists (select 1 from ins_tokens i join private.team_join_tokens j on j.token = i.token where j.team_id <> i.team_id) then
      raise exception 'restore_aborted: a join token of the backup is already used by another team';
    end if;
  end if;
  select count(*) into n from rt;
  if v_mode = 'commit' and n <> v_expect then
    raise exception 'restore_aborted: % whole team(s) would be restored but % were expected (state changed since plan, or already restored)', n, v_expect;
  end if;

  -- report before inserting: per table backup / present / differs / to restore / left out
  v_rep := format(E'target: %s (%s migrations) | backup: %s, taken %s | Auth users now %s (backup %s) | scope %s',
    v_target, cardinality(v_db), v_kind, left(b ->> 'taken_at', 16), (select count(*) from auth.users), coalesce(b ->> 'auth_users_count', '-'), v_scope);
  v_rep := v_rep || format(E'\nwhole teams to restore: %s | teams still present: %s', (select count(*) from rt), (select count(*) from et));
  for i in 0 .. jsonb_array_length(v_cfg) - 1 loop
    execute format('select count(*) filter (where d.ok), count(*) filter (where d.ok and not d.same) from (select exists (select 1 from %s r where (%s) = (%s)) ok, '
                   || 'coalesce((select to_jsonb(r) @> to_jsonb(b1) from %s r where (%s) = (%s)), false) same from %I b1) d',
      v_cfg -> i ->> 2, (select string_agg('r.' || trim(c), ', ') from unnest(string_to_array(v_cfg -> i ->> 3, ',')) c),
      (select string_agg('b1.' || trim(c), ', ') from unnest(string_to_array(v_cfg -> i ->> 3, ',')) c),
      v_cfg -> i ->> 2, (select string_agg('r.' || trim(c), ', ') from unnest(string_to_array(v_cfg -> i ->> 3, ',')) c),
      (select string_agg('b1.' || trim(c), ', ') from unnest(string_to_array(v_cfg -> i ->> 3, ',')) c),
      v_cfg -> i ->> 1) into n, m;
    execute format('select count(*) from %I', 'ins_' || case v_cfg -> i ->> 0
      when 'team_members' then 'members' when 'player_guardians' then 'guardians' when 'guardian_invitations' then 'invitations'
      when 'team_owner_transfers' then 'transfers' when 'account_deletions' then 'deletions' when 'team_join_tokens' then 'tokens'
      when 'team_member_blocks' then 'blocks' else v_cfg -> i ->> 0 end) into x;
    v_rep := v_rep || format(E'\n%s: backup %s | present %s (differs %s) | restore %s | left out %s',
      v_cfg -> i ->> 0, jsonb_array_length(b -> (v_cfg -> i ->> 0)), n, m, x, jsonb_array_length(b -> (v_cfg -> i ->> 0)) - n - x);
  end loop;
  if v_conf <> '' then
    v_rep := v_rep || E'\nnot restored, changed after the backup inside existing teams? ' || trim(v_conf);
  end if;

  -- ---------------------------------------------------------------
  -- 5. Insert in foreign-key order (no overwrite; every planned row must really be inserted)
  -- ---------------------------------------------------------------
  insert into public.teams select * from ins_teams on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_teams) then raise exception 'restore_aborted: teams changed during the restore'; end if;
  if v_target = 'latest' then
    if v_kind = 'latest' then
      -- the trigger just gave every restored team a NEW token: put the backed-up one (or the stopped state) back
      delete from private.team_join_tokens where team_id in (select id from rt);
      insert into private.team_join_tokens select * from ins_tokens;
    else
      select count(*) into v_new_tokens from private.team_join_tokens where team_id in (select id from rt);
    end if;
  end if;
  if v_kind = 'latest' then
    insert into public.team_members select * from ins_members on conflict do nothing;
  else
    insert into public.team_members (team_id, user_id, role, display_name, joined_at)
    select team_id, user_id, role, display_name, joined_at from ins_members on conflict do nothing;
  end if;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_members) then raise exception 'restore_aborted: memberships changed during the restore'; end if;
  if v_kind = 'latest' then
    insert into public.players select * from ins_players on conflict do nothing;
  else
    insert into public.players (id, team_id, name, normalized_name, note, created_by, created_at, archived_at, updated_at, updated_by, archived_by)
    select id, team_id, name, normalized_name, note, created_by, created_at, archived_at, updated_at, updated_by, archived_by from ins_players on conflict do nothing;
  end if;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_players) then raise exception 'restore_aborted: registrations changed during the restore'; end if;
  insert into public.player_guardians select * from ins_guardians on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_guardians) then raise exception 'restore_aborted: guardian links changed during the restore'; end if;
  insert into public.events select * from ins_events on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_events) then raise exception 'restore_aborted: events changed during the restore'; end if;
  insert into public.attendance select * from ins_attendance on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_attendance) then raise exception 'restore_aborted: answers changed during the restore'; end if;
  insert into public.guardian_invitations select * from ins_invitations on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_invitations) then raise exception 'restore_aborted: invitations changed during the restore'; end if;
  insert into public.team_owner_transfers select * from ins_transfers on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_transfers) then raise exception 'restore_aborted: owner hand-overs changed during the restore'; end if;
  if v_kind = 'latest' then
    insert into private.team_member_blocks select * from ins_blocks on conflict do nothing;
    get diagnostics n = row_count;
    if n <> (select count(*) from ins_blocks) then raise exception 'restore_aborted: re-join blocks changed during the restore'; end if;
  end if;
  -- last: a deletion-state row makes the triggers refuse new memberships of that user
  insert into private.account_deletions select * from ins_deletions on conflict do nothing;
  get diagnostics n = row_count;
  if n <> (select count(*) from ins_deletions) then raise exception 'restore_aborted: deletion records changed during the restore'; end if;

  set constraints all immediate;   -- the deferred checks (one owner per team, a guardian per child) run here

  -- ---------------------------------------------------------------
  -- 6. Security state of the whole database after the restore
  -- ---------------------------------------------------------------
  v_post := '';
  select count(*) into n from public.teams t1 where (select count(*) from public.team_members m where m.team_id = t1.id and m.role = 'owner') <> 1;
  if n > 0 then v_post := v_post || format(' teams_without_exactly_one_owner=%s', n); end if;
  select count(*) into n from public.players p where not exists (select 1 from public.player_guardians g where g.player_id = p.id);
  if n > 0 then v_post := v_post || format(' registrations_without_guardian=%s', n); end if;
  select count(*) into n from (
    select m.user_id from public.team_members m union all select g.user_id from public.player_guardians g
  ) u where u.user_id in (select user_id from private.account_deletions);
  if n > 0 then v_post := v_post || format(' data_of_users_in_deletion=%s', n); end if;
  select count(*) into n from pg_class c
   where c.oid in ('public.teams'::regclass, 'public.team_members'::regclass, 'public.players'::regclass, 'public.player_guardians'::regclass,
                   'public.events'::regclass, 'public.attendance'::regclass, 'public.guardian_invitations'::regclass,
                   'public.team_owner_transfers'::regclass, 'private.account_deletions'::regclass)
     and not c.relrowsecurity;
  if n > 0 then v_post := v_post || format(' tables_without_rls=%s', n); end if;
  if has_table_privilege('anon', 'private.account_deletions', 'select') or has_table_privilege('authenticated', 'private.account_deletions', 'select') then
    v_post := v_post || ' deletion_records_readable_by_app_users';
  end if;
  if v_target = 'latest' then
    execute $q$select count(*) from public.team_members m join private.team_member_blocks k on k.team_id = m.team_id and k.user_id = m.user_id$q$ into n;
    if n > 0 then v_post := v_post || format(' blocked_users_with_membership=%s', n); end if;
    execute $q$select count(*) from public.teams t1 where not exists (select 1 from private.team_join_tokens j where j.team_id = t1.id)$q$ into n;
    if n > 0 then v_post := v_post || format(' teams_without_join_token_row=%s', n); end if;
    execute $q$select count(*) from pg_class c where c.oid in ('private.team_join_tokens'::regclass, 'private.team_member_blocks'::regclass)
                and (not c.relrowsecurity or has_table_privilege('anon', c.oid, 'select') or has_table_privilege('authenticated', c.oid, 'select'))$q$ into n;
    if n > 0 then v_post := v_post || format(' private_tables_open=%s', n); end if;
    if has_function_privilege('anon', 'public.join_team(text,text)', 'execute') or has_function_privilege('authenticated', 'public.join_team(text,text)', 'execute')
       or has_function_privilege('anon', 'public.get_team_by_share_token(text)', 'execute')
       or has_function_privilege('authenticated', 'public.get_team_by_share_token(text)', 'execute') then
      v_post := v_post || ' legacy_join_reopened';
    end if;
  end if;
  v_rep := v_rep || E'\nnew join tokens (4-B backup into the latest schema: the old share links never had one): ' || v_new_tokens
                 || E'\npost-checks: ' || case when v_post = '' then 'ok' else trim(v_post) end;

  if v_mode = 'plan' then
    raise exception E'RESTORE_PLAN（変更なし・ロールバック済み）\n%', v_rep;
  end if;
  if v_post <> '' then
    raise exception E'restore_aborted: post-check failed, nothing was changed: %\n%', trim(v_post), v_rep;
  end if;
  raise notice E'RESTORE_DONE\n%', v_rep;
end
$restore$;
